#include<stdio.h>
#include<stdlib.h>
#include<math.h>
#include<ctype.h>
int top=-1,i;
float op1,op2;
float res,stack[10];
char symb,postfix[20];
void push(float item){
stack[++top]=item;
}
float pop(){
return stack[top--];
}
void main(){
printf("Enter the valid postfix expression:");
scanf("%d",postfix);
for(i=0;postfix[i]!='\0';i++){
symb=postfix[i];
if(isdigit(symb)){
push(symb-'0');
}
else{
op1=pop();
op2=pop();
switch(symb){
case '+':push(op2+op1);
break;
case '-':push(op2-op1);
break;
case '/':push(op2/op1);
break;
case '%':push(fmod(op2,op1));
break;
case '*':push(op2*op1);
break;
case '^':push(pow(op2,op1));
break;
default:push(0);
}
}
}
res=pop();
printf("The evaluated postfix expression is %f.",res);
}

